<?php

namespace Database\Seeders;

use App\Helpers\Helpers;
use App\Models\Currency;
use App\Models\Zone;
use Illuminate\Database\Seeder;
use MatanYadaev\EloquentSpatial\Objects\LineString;
use MatanYadaev\EloquentSpatial\Objects\Point;
use MatanYadaev\EloquentSpatial\Objects\Polygon;

/**
 * Зоны обслуживания: 18 административных районов Санкт-Петербурга + Гатчина.
 * Границы — упрощённые (Douglas-Peucker, ~200м) полигоны из OpenStreetMap
 * (Nominatim), не официальные кадастровые границы — этого достаточно для
 * зоны сервиса, недостаточно для юридических/кадастровых целей.
 *
 * Восстановлено 2026-09-26 после инцидента с тестовой БД (см. CLAUDE.md /
 * project_state) — зоны раньше существовали только как ручная настройка в
 * админке и были потеряны при случайном migrate:fresh. Теперь воспроизводимы
 * через db:seed.
 */
class SpbZoneSeeder extends Seeder
{
    public function run(): void
    {
        $currencyId = Currency::where('code', 'RUB')->where('status', true)->first()?->id
            ?? Currency::where('status', true)->first()?->id;

        $defaultPaymentMethods = collect(Helpers::getPaymentMethodConfigs())
            ->where('status', true)
            ->pluck('slug')
            ->toArray();

        $existingNames = Zone::withTrashed()->get()
            ->map(fn ($z) => $z->getTranslation('name', 'ru'))
            ->all();

        foreach (self::zones() as $name => $rawPoints) {
            if (in_array($name, $existingNames, true)) {
                continue;
            }

            $points = array_map(fn ($c) => new Point($c['lat'], $c['lng']), $rawPoints);
            if (head($points) != end($points)) {
                $points[] = head($points);
            }

            $zone = Zone::create([
                'name' => $name,
                'place_points' => new Polygon([new LineString($points)]),
                'locations' => $rawPoints,
                'status' => 1,
                'currency_id' => $currencyId,
                'payment_methods' => $defaultPaymentMethods,
            ]);

            $zone->setTranslation('name', 'ru', $name);
            $zone->save();
        }
    }

